1218	/* The design pins this block at top:512, which pushes its send button 30px past
1219	   the 813px canvas — the design PNG shows the same clipped button. Raised to
1220	   476 so the primary action is reachable; every internal offset is unchanged. */
1221	.tt-inv-form { position:absolute; left:668px; top:436px; width:430px; display:flex; flex-direction:column; gap:14px; animation:tileIn .35s cubic-bezier(.22,.9,.3,1) both; }
