export const RETAIL_STOCK = [
  { id: 1, name: "flat white", cost: "5.50", description: "double shot", emoji: "☕", variations: [] },
  { id: 2, name: "latte", cost: "6.00", description: "house blend", emoji: "☕", variations: [] },
