  phase = `nav ${nav}`;
  await page.getByRole("button", { name: nav, exact: true }).click();
  await page.waitForTimeout(1500);
}
for (const route of PUSH_ROUTES) {
  phase = `push ${route}`;
  await page.evaluate((p) => {
    history.pushState({}, "", p);
    window.dispatchEvent(new PopStateEvent("popstate"));
  }, route);
  await page.waitForTimeout(1500);
}

console.log("\n=== non-2xx responses ===");
for (const [k, n] of [...bad.entries()].sort()) console.log(`  x${n}  ${k}`);
if (!bad.size) console.log("  (none)");

await context.close();
await browser.close();

