/* Throwaway visual check: cascade filmstrip + the quick-invoice colour fix. */
import { mkdir } from "node:fs/promises";
import { chromium } from "playwright";
import { BASE_URL, newRetailPage, CHROMIUM_PATH } from "./retail-fixtures.mjs";

const OUT = "/tmp/claude-1000/-home-runner-workspace/5abb4202-8c03-4cd6-8a70-0593a874ca18/scratchpad/shots";
await mkdir(OUT, { recursive: true });

const browser = await chromium.launch({ executablePath: CHROMIUM_PATH });
const { context, page } = await newRetailPage(browser, "desktop", {
  viewport: { width: 1440, height: 900 },
});

await page.goto(`${BASE_URL}/dashboard`, { waitUntil: "networkidle" });
await page.getByTestId("desktop-frame").waitFor({ state: "visible" });
await page.waitForTimeout(20_000); // preload drain

/* 1. Cascade filmstrip of a nav hop. Frames every 90ms across the ~1s window. */
await page.getByRole("button", { name: "analytics", exact: true }).click();
await page.waitForTimeout(1400);
await page.getByRole("button", { name: "home", exact: true }).click();
for (let i = 0; i < 10; i++) {
  await page.screenshot({ path: `${OUT}/cascade-${String(i).padStart(2, "0")}-${i * 90}ms.png` });
  await page.waitForTimeout(90);
}
console.log("cascade filmstrip written");

/* 2. The quick-invoice panel, whose six colour declarations were empty. */
await page.evaluate(() => {
  history.pushState({}, "", "/trades/terminal?quick=1");
  window.dispatchEvent(new PopStateEvent("popstate"));
});
await page.waitForTimeout(2500);
await page.screenshot({ path: `${OUT}/trades-quick-invoice.png` });

/* Read back the computed colours so the fix is checkable as numbers too. */
const colours = await page.evaluate(() => {
  const pick = (sel) => {
    const el = document.querySelector(sel);
    if (!el) return `${sel} → NOT FOUND`;
    const cs = getComputedStyle(el);
    return `${sel} → color ${cs.color} / background ${cs.backgroundColor}`;
  };
  const pressed = [...document.querySelectorAll(".tt-quick-channel button")]
    .find((b) => b.getAttribute("aria-pressed") === "true");
  const unpressed = [...document.querySelectorAll(".tt-quick-channel button")]
    .find((b) => b.getAttribute("aria-pressed") !== "true");
  const fmt = (label, el) => {
    if (!el) return `${label} → NOT FOUND`;
    const cs = getComputedStyle(el);
    return `${label} → color ${cs.color} / background ${cs.backgroundColor}`;
  };
  return [
    pick(".tt-quick-recipient > input"),
    fmt("channel button [aria-pressed=true]", pressed),
    fmt("channel button [unpressed]", unpressed),
  ].join("\n");
});
console.log("\n=== computed colours ===\n" + colours);

await context.close();
await browser.close();

