/* Throwaway: capture the 15 app screens to pair against the design PNGs. */
import { mkdir } from "node:fs/promises";
import { chromium } from "playwright";
import { BASE_URL, newRetailPage, CHROMIUM_PATH } from "./retail-fixtures.mjs";

const OUT = "/tmp/claude-1000/-home-runner-workspace/5abb4202-8c03-4cd6-8a70-0593a874ca18/scratchpad/sbs";
await mkdir(OUT, { recursive: true });

/* design canvas is 1180x880; give the viewport enough room that ScaledCanvas
   settles at scale 1 so the capture is native, not resampled. */
const VIEWPORT = { width: 1700, height: 1150 };

const SCREENS = [
  ["retail", "dt--retail-home", "/dashboard"],
  ["retail", "dt--retail-stock", "/stock"],
  ["retail", "dt--retail-terminal", "/terminal"],
  ["retail", "dt--retail-analytics", "/transactions"],
  ["retail", "dt--retail-settings", "/settings"],
  ["property", "dt--home", "/property"],
  ["property", "dt--clients", "/property/tenants"],
  ["property", "dt--terminal", "/property/terminal"],
  ["property", "dt--analytics", "/property/analytics"],
  ["property", "dt--settings", "/settings"],
  ["trades", "dt--trades-home", "/trades"],
  ["trades", "dt--trades-clients", "/trades/clients"],
  ["trades", "dt--trades-terminal", "/trades/terminal"],
  ["trades", "dt--trades-analytics", "/trades/analytics"],
  ["trades", "dt--trades-settings", "/settings"],
];

const browser = await chromium.launch({ executablePath: CHROMIUM_PATH });
let reported = false;

for (const [mode, name, route] of SCREENS) {
  const { context, page } = await newRetailPage(browser, name, { viewport: VIEWPORT });
  /* taptMode decides which vertical the shared /settings route wears, and which
     nav the shell shows. Set before first paint. */
  await page.addInitScript((m) => localStorage.setItem("taptMode", m), mode);

  await page.goto(`${BASE_URL}${route}`, { waitUntil: "networkidle" });
  const frame = page.getByTestId("desktop-frame");
  await frame.waitFor({ state: "visible" });
  await page.waitForTimeout(2200); // let the cascade finish

  if (!reported) {
    const box = await frame.boundingBox();
    const scale = await page.evaluate(() => {
      const el = document.querySelector("[data-testid='desktop-frame']");
      const m = el && getComputedStyle(el.parentElement).transform;
      return m && m !== "none" ? m : "(no transform)";
    });
    console.log(`frame box ${box.width.toFixed(0)}x${box.height.toFixed(0)}  canvas transform ${scale}`);
    reported = true;
  }

  await frame.screenshot({ path: `${OUT}/app--${name}.png` });
  console.log(`captured ${name}  ←  ${route}  [${mode}]`);
  await context.close();
}

await browser.close();

