import { chromium } from "playwright";
import { BASE_URL, newRetailPage, CHROMIUM_PATH } from "./retail-fixtures.mjs";

const browser = await chromium.launch({ executablePath: CHROMIUM_PATH });
for (const [w, h] of [[1440, 900], [1280, 960], [1200, 940], [1194, 834], [1400, 1000], [1500, 1050], [1700, 1150]]) {
  const { context, page } = await newRetailPage(browser, "s", { viewport: { width: w, height: h } });
  await page.goto(`${BASE_URL}/dashboard`, { waitUntil: "networkidle" });
  await page.getByTestId("desktop-frame").waitFor({ state: "visible" });
  await page.waitForTimeout(1200);
  const info = await page.evaluate(() => {
    const c = document.querySelector("[data-testid='desktop-scaled-canvas']");
    const f = document.querySelector("[data-testid='desktop-frame']");
    const fb = f?.getBoundingClientRect();
    return {
      scale: c?.getAttribute("data-desktop-scale") ?? "(no canvas)",
      logical: c ? `${c.style.width}x${c.style.height}` : "-",
      frame: fb ? `${Math.round(fb.width)}x${Math.round(fb.height)}` : "-",
    };
  });
  console.log(`${w}x${h}  scale ${info.scale}  logical ${info.logical}  frame ${info.frame}`);
  await context.close();
}
await browser.close();

