/* Crop the app shots to the 13" frame and emit the side-by-side review page. */
import { readFileSync, writeFileSync, existsSync } from "node:fs";
import { PNG } from "/home/runner/workspace/node_modules/pngjs/lib/png.js";

/* The frame's box inside the 1440x900 shots, from verify-desktop-p0. */
const CROP = { x: 220, y: 77, w: 1000, h: 746 };
const DESIGN_DIR = "/home/runner/workspace/docs/design/desktop-app/screens";
const MINE = "/tmp/claude-1000/-home-runner-workspace/5abb4202-8c03-4cd6-8a70-0593a874ca18/scratchpad/sbs";

const PAIRS = [
  ["Retail", "Home", "dt--retail-home", "/tmp/taptpay-desktop-4a/desktop-1-home-week.png", "/dashboard"],
  ["Retail", "Stock", "dt--retail-stock", "/tmp/taptpay-desktop-4b/desktop-1-stock.png", "/stock"],
  ["Retail", "Terminal", "dt--retail-terminal", "/tmp/taptpay-desktop-4c/desktop-1-send.png", "/terminal"],
  ["Retail", "Analytics", "dt--retail-analytics", "/tmp/taptpay-desktop-4d/desktop-1-overview-week.png", "/transactions"],
  ["Retail", "Settings", "dt--retail-settings", "/tmp/taptpay-desktop-4e/desktop-1-business.png", "/settings"],
  ["Property", "Home", "dt--home", "/tmp/taptpay-desktop-2a/desktop-1-home-week.png", "/property"],
  ["Property", "Clients", "dt--clients", "/tmp/taptpay-desktop-2b/desktop-1-directory.png", "/property/tenants"],
  ["Property", "Terminal", "dt--terminal", "/tmp/taptpay-desktop-2c/desktop-1-request-empty.png", "/property/terminal"],
  ["Property", "Analytics", "dt--analytics", "/tmp/taptpay-desktop-2d/desktop-1-overview-year.png", "/property/analytics"],
  ["Property", "Settings", "dt--settings", "/tmp/taptpay-desktop-2e/desktop-1-settings-property.png", "/settings"],
  ["Trades", "Home", "dt--trades-home", "/tmp/taptpay-desktop-3a/desktop-1-default.png", "/trades"],
  ["Trades", "Clients", "dt--trades-clients", "/tmp/taptpay-desktop-3b/desktop-1-directory.png", "/trades/clients"],
  ["Trades", "Terminal", "dt--trades-terminal", "/tmp/taptpay-desktop-3c/desktop-1-invoice-empty.png", "/trades/terminal"],
  ["Trades", "Analytics", "dt--trades-analytics", "/tmp/taptpay-desktop-3d/desktop-1-overview-year.png", "/trades/analytics"],
  /* shot-trades-settings.mjs throws on its own strict-mode locator, so this one
     comes from a direct capture of the already-cropped logical canvas. */
  ["Trades", "Settings", "dt--trades-settings", `${MINE}/app--dt--trades-settings.png`, "/settings"],
];

const cropToDataUri = (file) => {
  const png = PNG.sync.read(readFileSync(file));
  /* The direct captures are already exactly the canvas — nothing to crop. */
  if (png.width <= CROP.w + 4) return `data:image/png;base64,${readFileSync(file).toString("base64")}`;
  const out = new PNG({ width: CROP.w, height: CROP.h });
  PNG.bitblt(png, out, CROP.x, CROP.y, CROP.w, CROP.h, 0, 0);
  return `data:image/png;base64,${PNG.sync.write(out).toString("base64")}`;
};

const asDataUri = (file) => `data:image/png;base64,${readFileSync(file).toString("base64")}`;

const rows = [];
for (const [vertical, screen, design, appShot, route] of PAIRS) {
  const designFile = `${DESIGN_DIR}/${design}.png`;
  if (!existsSync(designFile)) throw new Error(`missing design ${designFile}`);
  if (!existsSync(appShot)) throw new Error(`missing app shot ${appShot}`);
  rows.push({
    vertical,
    screen,
    route,
    design: asDataUri(designFile),
    app: cropToDataUri(appShot),
  });
  console.log(`paired ${vertical}/${screen}`);
}

const section = (r, i) => `
<section class="pair" id="p${i}">
  <header class="pair-head">
    <h2><span class="vert v-${r.vertical.toLowerCase()}">${r.vertical}</span> ${r.screen}</h2>
    <code>${r.route}</code>
  </header>
  <div class="shots">
    <figure><figcaption>Design</figcaption><img loading="lazy" alt="${r.vertical} ${r.screen} design" src="${r.design}"></figure>
    <figure><figcaption>Built app</figcaption><img loading="lazy" alt="${r.vertical} ${r.screen} built" src="${r.app}"></figure>
  </div>
</section>`;

const html = `<title>Desktop app — design vs build</title>
<style>
  :root {
    --bg: #f6f7fb; --panel: #ffffff; --ink: #12162e; --soft: #5b6280;
    --line: #e2e5ef; --accent: #2f6df6;
    --retail: #2f6df6; --property: #12a5a0; --trades: #e0842b;
  }
  :root:not([data-theme="light"]) { }
  @media (prefers-color-scheme: dark) {
    :root:not([data-theme="light"]) {
      --bg: #0a0e1c; --panel: #121828; --ink: #eef1fa; --soft: #98a0bd;
      --line: #232b42; --accent: #6f9dff;
      --retail: #6f9dff; --property: #35c9c3; --trades: #f0a34e;
    }
  }
  :root[data-theme="dark"] {
    --bg: #0a0e1c; --panel: #121828; --ink: #eef1fa; --soft: #98a0bd;
    --line: #232b42; --accent: #6f9dff;
    --retail: #6f9dff; --property: #35c9c3; --trades: #f0a34e;
  }
  * { box-sizing: border-box; }
  body {
    margin: 0; background: var(--bg); color: var(--ink);
    font: 15px/1.55 ui-sans-serif, system-ui, -apple-system, "Segoe UI", sans-serif;
    padding: 40px 24px 80px;
  }
  .wrap { max-width: 1500px; margin: 0 auto; }
  h1 { font-size: 26px; margin: 0 0 6px; letter-spacing: -0.01em; }
  .lede { color: var(--soft); margin: 0 0 10px; max-width: 74ch; }
  .note {
    background: var(--panel); border: 1px solid var(--line); border-left: 3px solid var(--accent);
    border-radius: 8px; padding: 12px 16px; margin: 20px 0 34px; max-width: 90ch; color: var(--soft);
  }
  .note strong { color: var(--ink); }
  .pair { margin: 0 0 44px; }
  .pair-head {
    display: flex; align-items: baseline; gap: 12px; flex-wrap: wrap;
    padding-bottom: 8px; margin-bottom: 12px; border-bottom: 1px solid var(--line);
  }
  .pair-head h2 { font-size: 17px; margin: 0; font-weight: 650; }
  .vert { font-weight: 750; }
  .v-retail { color: var(--retail); } .v-property { color: var(--property); } .v-trades { color: var(--trades); }
  .pair-head code { color: var(--soft); font-size: 12.5px; }
  .shots { display: grid; grid-template-columns: 1fr 1fr; gap: 18px; }
  @media (max-width: 900px) { .shots { grid-template-columns: 1fr; } }
  figure { margin: 0; }
  figcaption {
    font-size: 11px; text-transform: uppercase; letter-spacing: 0.09em;
    color: var(--soft); margin-bottom: 6px; font-weight: 600;
  }
  img {
    width: 100%; max-width: 100%; display: block; border-radius: 10px;
    border: 1px solid var(--line); background: #001030;
  }
</style>
<div class="wrap">
  <h1>Tablet/desktop app — design vs build</h1>
  <p class="lede">All 15 screens (3 verticals x 5), design source on the left, the built app on the right.</p>
  <div class="note">
    <strong>How to read these.</strong> Both panes are the same 1180x880 logical canvas at the same
    aspect ratio, so they overlay directly — differences in position and spacing are real, not artefacts
    of capture. The built shots use each screen's own fixture data, so <em>content</em> deliberately
    differs from the design's filler (the design repeats one placeholder row; the build shows a handful
    of realistic records). Judge layout, spacing, type scale and colour — not the words or the row counts.
  </div>
  ${rows.map(section).join("\n")}
</div>`;

writeFileSync(
  "/tmp/claude-1000/-home-runner-workspace/5abb4202-8c03-4cd6-8a70-0593a874ca18/scratchpad/desktop-sbs.html",
  html,
);
console.log(`\nwrote page, ${(Buffer.byteLength(html) / 1024 / 1024).toFixed(2)} MB`);

